# Shell integration for the `a` CLI. Source it from ~/.zshrc or ~/.bashrc:
#
#   [ -f "$HOME/.a/init.sh" ] && . "$HOME/.a/init.sh"
#
# Defines an `a` function rather than putting the script on $PATH so that, when
# an interactive pick resolves to a full command (e.g. `a` → `a font-size 1.15`),
# that one-liner lands in shell history ready to rerun with ↑.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool

if [ -n "${ZSH_VERSION:-}" ]; then
  _A_ROOT="${${(%):-%x}:A:h}"
else
  _A_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
fi

unalias a 2>/dev/null

a() {
  local out rc resolved
  out="$(mktemp)"
  A_RESOLVED_FILE="$out" "$_A_ROOT/a" "$@"
  rc=$?
  resolved="$(cat "$out")"
  rm -f "$out"
